menv python -c "
import json
for fid in (6,):
    m=json.load(open('data/%d/metadata.json'%fid))
    ins=m.get('instruments',{})
    for k in ins:
        if k.startswith('sr'):
            p=ins[k]['snapshot']['parameters']
            for pn in ('time_constant','filter_slope','sensitivity','amplitude','frequency','phase','reserve'):
                if pn in p: print(k,pn,'=',p[pn].get('value'))
            print()
